function P(clase, pregunta, correcta, distractores, porque) {
  return {
    clase,
    pregunta,
    opciones: [{ texto: correcta, ok: true }].concat(distractores.map(function (t) { return { texto: t, ok: false }; })),
    porque
  };
}

